const dashboardZones = `-- name: DashboardZones :many
SELECT
  z.slug,
  z.name,
  z.type,
  r.version AS release_version,
  d.created_at AS deployed_at,
  u.name AS deployed_by,
  (SELECT count(*) FROM instance i
     WHERE i.deployment_zone_id = z.id)::bigint AS instances,
  (SELECT count(*) FROM release n
     WHERE n.organization_id = z.organization_id AND n.created_at > r.created_at)::bigint AS releases_behind
FROM deployment_zone z
LEFT JOIN LATERAL (
  SELECT d0.release_id, d0.created_at, d0.created_by_id
  FROM deployment d0
  WHERE d0.deployment_zone_id = z.id
  ORDER BY d0.created_at DESC, d0.seq DESC
  LIMIT 1
) d ON true
LEFT JOIN release r ON r.id = d.release_id
LEFT JOIN "user" u ON u.id = d.created_by_id
WHERE z.organization_id = $1
ORDER BY z.name
`

type DashboardZonesRow struct {
	Slug           string           `json:"slug"`
	Name           string           `json:"name"`
	Type           string           `json:"type"`
	ReleaseVersion *string          `json:"release_version"`
	DeployedAt     pgtype.Timestamp `json:"deployed_at"`
	DeployedBy     *string          `json:"deployed_by"`
	Instances      int64            `json:"instances"`
	ReleasesBehind int64            `json:"releases_behind"`
}

// Each zone with its latest deployment, from the journal, and how many
// releases were created after the one it runs.
func (q *Queries) DashboardZones(ctx context.Context, organizationID uuid.UUID) ([]DashboardZonesRow, error) {
	rows, err := q.db.Query(ctx, dashboardZones, organizationID)
	if err != nil {
		return nil, err
	}
	defer rows.Close()
	var items []DashboardZonesRow
	for rows.Next() {
		var i DashboardZonesRow
		if err := rows.Scan(
			&i.Slug,
			&i.Name,
			&i.Type,
			&i.ReleaseVersion,
			&i.DeployedAt,
			&i.DeployedBy,
			&i.Instances,
			&i.ReleasesBehind,
		); err != nil {
			return nil, err
		}
		items = append(items, i)
	}
	if err := rows.Err(); err != nil {
		return nil, err
	}
	return items, nil
}
